#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Seed A as a unit lower-triangular-like matrix. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     This computes B = A * A^T (a Gram matrix) and then sets A := B.
     We keep the same mathematical computation:
       B[r][s] = sum_t A[r][t] * A[s][t],
     but use cache-blocked loops for better locality. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Efficiently zero-initialize B.  POLYBENCH_2D_ARRAY_DECL allocates
     B as a contiguous n-by-n block, so a single memset is safe. */
  memset((void*)POLYBENCH_ARRAY(B), 0,
         (size_t)n * (size_t)n * sizeof(DATA_TYPE));

  /* Block sizes chosen to fit well in cache; can be tuned. */
  const int block = 32;
  int ii, jj, kk;

  /* Compute B = A * A^T with 3D blocking:
       for r, s:  B[r][s] += sum_t A[r][t] * A[s][t]
     The blocking reorders loops but keeps, for each (r,s), the same
     set of products; only the accumulation order over t changes. */
  for (ii = 0; ii < n; ii += block)
    {
      int i_max = ii + block;
      if (i_max > n) i_max = n;

      for (jj = 0; jj < n; jj += block)
        {
          int j_max = jj + block;
          if (j_max > n) j_max = n;

          for (kk = 0; kk < n; kk += block)
            {
              int k_max = kk + block;
              if (k_max > n) k_max = n;

              for (r = ii; r < i_max; ++r)
                {
                  for (s = jj; s < j_max; ++s)
                    {
                      DATA_TYPE sum = (POLYBENCH_ARRAY(B))[r][s];
                      for (t = kk; t < k_max; ++t)
                        sum += A[r][t] * A[s][t];
                      (POLYBENCH_ARRAY(B))[r][s] = sum;
                    }
                }
            }
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;
  int jj;

  /* Local restricted alias improves the compiler's ability to reason
     about aliasing.  We only access the matrix through A_. */
  DATA_TYPE (*restrict A_)[n] = A;

  /* Tile size for the upper (U) update along the column (j) dimension.
     This value is a reasonable default for modern x64 CPUs but can be
     tuned experimentally. */
  const int tile_j = 64;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    /* Pointer to the current row i, reused across inner loops. */
    DATA_TYPE *Ai = A_[i];

    /* ------------------------------------------------------------
       1. Strict lower-triangular part: compute L(i, j) for j < i.
          Each entry:
             A[i][j] = (A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j])
                       / A[j][j];
       ------------------------------------------------------------ */
    for (j = 0; j < i; j++) {

      DATA_TYPE sum = Ai[j];

      /* Accumulate the inner product in a register, with small
         unrolling over k to improve ILP and help the compiler
         generate good code. */
      int k_limit = j;

      for (k = 0; k + 3 < k_limit; k += 4) {
        sum -= Ai[k]     * A_[k][j];
        sum -= Ai[k + 1] * A_[k + 1][j];
        sum -= Ai[k + 2] * A_[k + 2][j];
        sum -= Ai[k + 3] * A_[k + 3][j];
      }
      for (; k < k_limit; ++k) {
        sum -= Ai[k] * A_[k][j];
      }

      Ai[j] = sum / A_[j][j];
    }

    /* ------------------------------------------------------------
       2. Upper-triangular part (including diagonal): compute U(i, j)
          for j >= i.

          Original code:
            for (j = i; j < N; j++)
              for (k = 0; k < i; k++)
                A[i][j] -= A[i][k] * A[k][j];

          Here we:
            - work on tiles of columns [jj, j_end),
            - for each tile, apply the rank-1 updates over all k:
                A[i][j] -= A[i][k] * A[k][j];

          For each fixed (i, j), the sequence of updates over k is still
          in increasing order k = 0..i-1, exactly as in the original
          kernel. Only the interleaving between different j's changes,
          which does not affect the value of A[i][j].
       ------------------------------------------------------------ */

    /* Parallelize across column tiles.  When compiled with OpenMP
       support (-fopenmp), this distributes disjoint column ranges
       [jj, j_end) of row i across threads.  Without OpenMP, the
       pragma is ignored and the code runs sequentially. */
#pragma omp parallel for schedule(static) if (_PB_N >= 64)
    for (jj = i; jj < _PB_N; jj += tile_j) {

      int j_end = jj + tile_j;
      if (j_end > _PB_N)
        j_end = _PB_N;

      /* For each previously computed column k of L(i, *), perform
         a rank-1 update on the tile [jj, j_end) of the U row. */
      int k_local;
      for (k_local = 0; k_local < i; ++k_local) {

        DATA_TYPE lik = Ai[k_local];      /* L(i, k) */
        DATA_TYPE *Ak = A_[k_local];      /* Row k of U */

        int j_local = jj;

        /* Unroll the inner j loop to expose ILP and aid auto-SIMD. */
        for (; j_local + 3 < j_end; j_local += 4) {
          Ai[j_local]     -= lik * Ak[j_local];
          Ai[j_local + 1] -= lik * Ak[j_local + 1];
          Ai[j_local + 2] -= lik * Ak[j_local + 2];
          Ai[j_local + 3] -= lik * Ak[j_local + 3];
        }
        for (; j_local < j_end; ++j_local) {
          Ai[j_local] -= lik * Ak[j_local];
        }
      } /* end loop over k_local */
    }   /* end loop over jj (column tiles) */

  } /* end loop over i */
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
