#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

/* Tiling factor for the upper-triangular update in kernel_lu.
 * Chosen to balance cache locality and vectorization. */
#ifndef LU_BLOCK_J
# define LU_BLOCK_J 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite. */
  /* not necessary for LU, but using same code as cholesky */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] += A[r][t] * A[s][t];
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	A[r][s] = (POLYBENCH_ARRAY(B))[r][s];
  POLYBENCH_FREE_ARRAY(B);

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* The optimized kernel keeps the mathematical algorithm identical:
   *
   *   - First compute the strict lower part of row i (L(i, j), j < i)
   *     in a left-looking manner (same dependencies/order in j as
   *     the original code).
   *
   *   - Then compute the upper part of row i (U(i, j), j >= i).
   *     We reformulate the second phase into a right-looking
   *     rank-1 update:
   *
   *         for (k = 0; k < i; ++k) {
   *           let L(i,k) = A[i][k];
   *           for (j = i; j < n; ++j)
   *             A[i][j] -= L(i,k) * A[k][j];
   *         }
   *
   *     This is algebraically equivalent to the original
   *
   *         for (j = i; j < n; ++j)
   *           for (k = 0; k < i; ++k)
   *             A[i][j] -= A[i][k] * A[k][j];
   *
   *     and preserves the order of operations on each A[i][j], while
   *     improving data locality by streaming over contiguous pieces of
   *     rows i and k. We additionally tile the j-dimension to make
   *     better use of caches and SIMD.
   */

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Pointer to the current row, to improve locality and enable
     * the compiler to generate better code. Each row A[i] is a
     * distinct sub-object, so A_i does not alias other rows. */
    DATA_TYPE *restrict A_i = A[i];

    /* 1. Strict lower triangle: compute L(i, j) for 0 <= j < i.
     *
     *    Original:
     *      for (j = 0; j < i; ++j) {
     *        for (k = 0; k < j; ++k)
     *          A[i][j] -= A[i][k] * A[k][j];
     *        A[i][j] /= A[j][j];
     *      }
     *
     *    We keep the same loop ordering and dependencies, but hold
     *    A[i][j] in a scalar accumulator ('sum') to reduce memory
     *    traffic and expose the inner product as a clear reduction. */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = A_i[j];
      for (k = 0; k < j; k++) {
        sum -= A_i[k] * A[k][j];
      }
      A_i[j] = sum / A[j][j];
    }

    /* 2. Upper triangle (including diagonal): compute U(i, j) for j >= i
     *    using a right-looking, blocked rank-1 update.
     *
     *    Structure per row i:
     *      for (k = 0; k < i; ++k) {
     *        DATA_TYPE lik = A[i][k];
     *        for (j = i; j < n; ++j)
     *          A[i][j] -= lik * A[k][j];
     *      }
     *
     *    We additionally tile columns (j) by LU_BLOCK_J to improve
     *    cache locality when streaming rows i and k, and to provide
     *    a good unit-stride inner loop for vectorization.
     *
     *    The order of updates for each element A[i][j] over k remains
     *    0..i-1, i.e., identical to the original kernel, so the
     *    per-entry computation order is preserved. */
    for (int jj = i; jj < _PB_N; jj += LU_BLOCK_J) {
      int j_end = jj + LU_BLOCK_J < _PB_N ? jj + LU_BLOCK_J : _PB_N;
      int width = j_end - jj;

      for (k = 0; k < i; k++) {
        DATA_TYPE lik = A_i[k];      /* L(i, k) multiplier */
        DATA_TYPE *restrict A_k = A[k];
        DATA_TYPE *restrict A_kj = &A_k[jj];  /* U(k, jj..j_end-1) */
        DATA_TYPE *restrict A_ij = &A_i[jj];  /* U(i, jj..j_end-1) */

        /* Inner loop over contiguous columns; ideal for SIMD. */
        #pragma GCC ivdep
        for (int offset = 0; offset < width; ++offset) {
          A_ij[offset] -= lik * A_kj[offset];
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

