   - We still compute an in-place LU factorization without pivoting,
     storing:
       * L in the strict lower triangle of A (unit diagonal implied),
       * U in the upper triangle of A, including the diagonal.

   - The algorithm is the same Doolittle scheme as the original:
       L(i,j) = ( A(i,j) - sum_{k<j} L(i,k)*U(k,j) ) / U(j,j)   for j<i
       U(i,j) =   A(i,j) - sum_{k<i} L(i,k)*U(k,j)              for j>=i

   - Key optimizations:

     1. Use a scalar accumulator 'sum' for each A[i][j] so that the
        element is loaded once, updated in registers during the k-reduction,
        and written back once. This reduces memory traffic and helps the
        compiler recognize the inner loops as pure reductions.

     2. Precompute and cache the reciprocals of the pivots:
          inv_diag[j] = 1 / A[j][j]
        so that each L-update uses a multiplication instead of a division.
        This replaces O(n^2) divisions by O(n^2) multiplications plus
        only O(n) divisions.

     3. Tile the upper update (j > i) along the column dimension. The
        inner-most loop then iterates over a contiguous stretch of columns,
        which improves spatial locality for A[i][j] and A[k][j] and helps
        the compiler vectorize the update.

   - All loop transformations preserve the mathematical computation of L
     and U; only the evaluation order of independent operations is changed.
*/
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Store 1 / A[j][j] for each pivot row j.
     Size is O(n), negligible compared to the O(n^2) matrix A. */
  DATA_TYPE inv_diag[n];

  /* Tunable tile size for the j-dimension in the upper update.
     64 is a reasonable default for modern x86-64 caches. */
  const int tile_j = 64;

#pragma scop
  for (i = 0; i < n; i++)
  {
    /* -------------------------------------------------------------
     * 1. Strict lower triangle: compute L(i, j) for 0 <= j < i
     *
     *    L(i, j) = ( A(i, j) - sum_{k=0}^{j-1} L(i, k) * U(k, j) ) / U(j, j)
     *
     * At this point, all rows 0..i-1 are complete (L and U), so
     *   - A[i][k] for k<j already holds L(i, k),
     *   - A[k][j] for k<j holds U(k, j),
     *   - inv_diag[j] = 1 / U(j, j) was computed when row j was finished.
     * ------------------------------------------------------------- */
    for (j = 0; j < i; j++)
    {
      DATA_TYPE sum = A[i][j];

      /* Left-looking inner product:
         sum -= sum_{k=0}^{j-1} L(i, k) * U(k, j) */
      for (k = 0; k < j; k++)
      {
        sum -= A[i][k] * A[k][j];
      }

      /* Replace division by multiplication with precomputed reciprocal. */
      sum *= inv_diag[j];
      A[i][j] = sum; /* L(i, j) */
    }

    /* -------------------------------------------------------------
     * 2. Diagonal element: compute U(i, i)
     *
     *    U(i, i) = A(i, i) - sum_{k=0}^{i-1} L(i, k) * U(k, i)
     *
     * This is the j == i case of the original upper-triangular loop.
     * ------------------------------------------------------------- */
    {
      DATA_TYPE sum = A[i][i];

      for (k = 0; k < i; k++)
      {
        sum -= A[i][k] * A[k][i];
      }

      A[i][i] = sum;              /* U(i, i) */
      inv_diag[i] = (DATA_TYPE)1.0 / sum;  /* cache 1 / U(i, i) */
    }

    /* -------------------------------------------------------------
     * 3. Upper triangle: compute U(i, j) for j > i
     *
     *    U(i, j) = A(i, j) - sum_{k=0}^{i-1} L(i, k) * U(k, j)
     *
     * We tile the j-dimension so that the innermost loop runs over
     * contiguous columns j in [jb, j_end). This improves cache reuse
     * and gives the compiler a long, straight-line loop to vectorize.
     * ------------------------------------------------------------- */
    int jb;
    for (jb = i + 1; jb < n; jb += tile_j)
    {
      int j_end = jb + tile_j;
      if (j_end > n)
        j_end = n;

      for (j = jb; j < j_end; j++)
      {
        DATA_TYPE sum = A[i][j];

        for (k = 0; k < i; k++)
        {
          sum -= A[i][k] * A[k][j];
        }

        A[i][j] = sum;  /* U(i, j) */
      }
    }
  }
#pragma endscop
}


