/* Array initialization.
 *
 * 1) Build a simple lower-triangular matrix with unit diagonal in A.
 * 2) Form a symmetric positive semi-definite matrix by computing
 *        B = A * A^T
 *    and then copying B back into A.
 *
 * The original code computed B via a naïve triple loop:
 *   B[r][s] += A[r][t] * A[s][t]
 * with t outermost. Here we recognize this as a Gram matrix and:
 *   - Exploit symmetry: only compute B[r][s] for r <= s and mirror.
 *   - Use a blocked dot-product over t to improve cache locality.
 *   - Access rows of A contiguously in the innermost loop to aid
 *     vectorization and reduce cache misses.
 *
 * The mathematical result A := A * A^T is preserved.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Seed A as unit lower-triangular-like. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite: A := A * A^T. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Use restrict-qualified row-major pointers to help the compiler
     reason about aliasing and to make the code more amenable to
     vectorization. */
  DATA_TYPE (*restrict a)[n] = A;
  DATA_TYPE (*restrict b)[n] = POLYBENCH_ARRAY(B);

  /* Tiling parameters for the Gram matrix construction.
     These are modest values chosen to fit working sets into caches
     on typical x64 machines; they can be tuned further if desired. */
  const int tile_r = 32;
  const int tile_s = 32;
  const int tile_t = 32;

  /* Compute B = A * A^T.
   *
   * We only compute the upper triangle (r <= s) and then mirror it to
   * the lower triangle. For each pair (r, s), we evaluate the dot
   * product of rows r and s of A:
   *
   *   B[r][s] = sum_t A[r][t] * A[s][t]
   *
   * The innermost loop runs along contiguous elements of the rows of A,
   * which is cache- and SIMD-friendly. Blocking in the t-dimension
   * improves temporal locality for slices of A.
   */
  for (int rr = 0; rr < n; rr += tile_r)
    {
      int r_end = rr + tile_r;
      if (r_end > n)
        r_end = n;

      /* Start ss from rr to restrict to the upper triangle; the
         (r > s) cases are filled in by symmetry below. */
      for (int ss = rr; ss < n; ss += tile_s)
        {
          int s_end = ss + tile_s;
          if (s_end > n)
            s_end = n;

          for (r = rr; r < r_end; ++r)
            {
              /* For a given row r in this block, columns s start at
                 max(r, ss) to ensure we only do work for r <= s. */
              int s_start = (r > ss) ? r : ss;

              for (s = s_start; s < s_end; ++s)
                {
                  DATA_TYPE sum = 0;

                  /* Block the reduction over t to keep small
                     segments of A[r][*] and A[s][*] hot in cache. */
                  for (int tt = 0; tt < n; tt += tile_t)
