                      /* Vectorizable inner loop: contiguous rows. */
                      for (t = tt; t < t_end; ++t)
                        sum += a[r][t] * a[s][t];
                    }

                  b[r][s] = sum;
                  /* Exploit symmetry: fill the lower triangle. */
                  if (r != s)
                    b[s][r] = sum;
                }
            }
        }
    }

  /* Copy the resulting Gram matrix back to A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      a[r][s] = b[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


