 *
 * Original algorithm (for each row i):
 *
 *   // Strict lower triangle: L(i, j), j < i
 *   for j in 0 .. i-1:
 *     for k in 0 .. j-1:
 *       A[i][j] -= A[i][k] * A[k][j];
 *     A[i][j] /= A[j][j];
 *
 *   // Upper triangle including diagonal: U(i, j), j >= i
 *   for j in i .. n-1:
 *     for k in 0 .. i-1:
 *       A[i][j] -= A[i][k] * A[k][j];
 *
 * We transform this to a right-looking, panel-update style formulation:
 *
 *   for i = 0 .. n-1:
 *     for k = 0 .. i-1:
 *       // Form L(i, k)
 *       A[i][k] /= A[k][k];
 *       // Rank-1 update of the trailing part of row i:
 *       //   A(i, j) -= L(i, k) * U(k, j), for j > k
 *       for j = k+1 .. n-1:
 *         A[i][j] -= A[i][k] * A[k][j];
 *
 * This is mathematically equivalent and, for each element A[i][j],
 * performs exactly the same sequence of arithmetic operations as
 * the original code (only interleaved differently with operations on
 * other elements). This preserves the numerical behavior while:
 *
 *   - Reusing A[i][k] across the whole row i in inner loops.
 *   - Accessing rows i and k contiguously in the innermost loop.
 *   - Allowing cache blocking and auto-vectorization along j.
 */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Row-major, restrict-qualified view of A for better optimization. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Tile size along the column dimension for the rank-1 updates.
     This is a tuning parameter; 64 works well on many x64 systems. */
  const int tile_j = 64;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Pointer to the current row i. */
      DATA_TYPE *restrict Ai = a[i];

      /* Process all previous columns k < i. Each iteration:
         - Finalizes L(i, k) in Ai[k],
         - Applies a rank-1 update to the remainder of row i. */
      for (k = 0; k < i; ++k)
